var documenterSearchIndex = {"docs":
[{"category":"section","location":"#TurboVec.jl","page":"Home","text":"A Julia port of turbovec, a vector index built on Google Research's TurboQuant algorithm: vectors are compressed to 2–4 bits per coordinate by a deterministic random rotation and scored directly against a per-query lookup table — no training phase, no decompression, online ingest, multithreaded search.\n\nusing TurboVec\n\nindex = TurboQuantIndex(1536, 4)     # dim, bits per coordinate\nadd!(index, X)                       # X::Matrix{Float32}, n × 1536\nscores, ids = search(index, Q, 10)   # Q::Matrix{Float32}, nq × 1536\n\nThe full reference — algorithm, API, persistence, filtering, thread and precision notes, performance vs the Rust implementation, and the development tooling — lives in the README.","title":"TurboVec.jl"},{"category":"section","location":"#API","page":"Home","text":"","title":"API"},{"category":"module","location":"#TurboVec.TurboVec","page":"Home","text":"TurboVec\n\nJulia port of turbovec, a vector index built on Google Research's TurboQuant algorithm: data-oblivious scalar quantization of rotated unit vectors to 2-4 bits per coordinate, with SIMD-free but cache-aware blocked scoring and a multi-threaded scan.\n\nPublic surface:\n\nTurboQuantIndex(dim, bit_width)\nadd!(index, vectors)\ncalibrate!(index, sample)\nsearch(index, queries, k)         -> (scores, indices)\nIdMapIndex(dim, bit_width)\nadd_with_ids!(index, vectors, ids)\nremove!(index, id)\nwrite_index(path, index) / load_index(path)\nwrite_idmap(path, index) / load_idmap(path)\n\n\n\n\n\n","title":"TurboVec.TurboVec"},{"category":"constant","location":"#TurboVec.MAX_DIM","page":"Home","text":"Maximum supported dimensionality.\n\n\n\n\n\n","title":"TurboVec.MAX_DIM"},{"category":"constant","location":"#TurboVec.MAX_VECTOR_SCALE","page":"Home","text":"Largest per-vector renormalization scale that cannot by itself overflow.\n\n\n\n\n\n","title":"TurboVec.MAX_VECTOR_SCALE"},{"category":"constant","location":"#TurboVec.MIN_CALIBRATION_ROWS","page":"Home","text":"Fewest rows a calibration fit can structurally use.\n\n\n\n\n\n","title":"TurboVec.MIN_CALIBRATION_ROWS"},{"category":"constant","location":"#TurboVec.MIN_INPUT_NORM","page":"Home","text":"L2 norm at or below which a vector has no representable direction.\n\nSuch a vector is stored with scale 0 (it scores 0 against every query), not rejected.\n\n\n\n\n\n","title":"TurboVec.MIN_INPUT_NORM"},{"category":"constant","location":"#TurboVec.RECOMMENDED_CALIBRATION_ROWS","page":"Home","text":"Calibration sample size to aim for (advisory, not enforced).\n\n\n\n\n\n","title":"TurboVec.RECOMMENDED_CALIBRATION_ROWS"},{"category":"type","location":"#TurboVec.AllowlistEmpty","page":"Home","text":"An allowlist was passed empty.\n\n\n\n\n\n","title":"TurboVec.AllowlistEmpty"},{"category":"type","location":"#TurboVec.BitWidthOutOfRange","page":"Home","text":"Bit width outside {2, 3, 4}.\n\n\n\n\n\n","title":"TurboVec.BitWidthOutOfRange"},{"category":"type","location":"#TurboVec.Codebook","page":"Home","text":"Named codebook arrays: (boundaries = …, centroids = …).\n\n\n\n\n\n","title":"TurboVec.Codebook"},{"category":"type","location":"#TurboVec.DegenerateSample","page":"Home","text":"Calibration sample has no per-coordinate spread anywhere (fits identity).\n\n\n\n\n\n","title":"TurboVec.DegenerateSample"},{"category":"type","location":"#TurboVec.DimMismatch","page":"Home","text":"Operation's dimensionality does not match the index's committed dim.\n\n\n\n\n\n","title":"TurboVec.DimMismatch"},{"category":"type","location":"#TurboVec.DimNotPositiveMultipleOf8","page":"Home","text":"Index dimensionality not a positive multiple of 8.\n\n\n\n\n\n","title":"TurboVec.DimNotPositiveMultipleOf8"},{"category":"type","location":"#TurboVec.DimTooLarge","page":"Home","text":"Index dimensionality above MAX_DIM.\n\n\n\n\n\n","title":"TurboVec.DimTooLarge"},{"category":"type","location":"#TurboVec.DuplicateIdInBatch","page":"Home","text":"add_with_ids! was given the same id twice in one batch.\n\n\n\n\n\n","title":"TurboVec.DuplicateIdInBatch"},{"category":"type","location":"#TurboVec.EmptyCalibrationSample","page":"Home","text":"Calibration sample has fewer rows than MIN_CALIBRATION_ROWS.\n\n\n\n\n\n","title":"TurboVec.EmptyCalibrationSample"},{"category":"type","location":"#TurboVec.IdAlreadyPresent","page":"Home","text":"add_with_ids! was given an id that is already in the index.\n\n\n\n\n\n","title":"TurboVec.IdAlreadyPresent"},{"category":"method","location":"#TurboVec.IdMapIndex-Tuple{Integer, Integer}","page":"Home","text":"IdMapIndex(dim, bit_width)\n\nAn id-map index with a known dimensionality.\n\n\n\n\n\n","title":"TurboVec.IdMapIndex"},{"category":"method","location":"#TurboVec.IdMapIndex-Tuple{Integer}","page":"Home","text":"IdMapIndex(bit_width)\n\nAn id-map index without a committed dim; inferred on the first add.\n\n\n\n\n\n","title":"TurboVec.IdMapIndex"},{"category":"type","location":"#TurboVec.IdsCountMismatch","page":"Home","text":"Number of ids does not match the number of vectors.\n\n\n\n\n\n","title":"TurboVec.IdsCountMismatch"},{"category":"type","location":"#TurboVec.InvalidFileFormat","page":"Home","text":"A persisted image is malformed, truncated, or fails validation.\n\n\n\n\n\n","title":"TurboVec.InvalidFileFormat"},{"category":"type","location":"#TurboVec.InvalidInputValue","page":"Home","text":"Added vector has a non-finite or over-magnitude coordinate.\n\n\n\n\n\n","title":"TurboVec.InvalidInputValue"},{"category":"type","location":"#TurboVec.InvalidParts","page":"Home","text":"from_parts was given an inconsistent or out-of-bounds part.\n\n\n\n\n\n","title":"TurboVec.InvalidParts"},{"category":"type","location":"#TurboVec.InvalidQueryValue","page":"Home","text":"Query has a non-finite or over-magnitude coordinate.\n\n\n\n\n\n","title":"TurboVec.InvalidQueryValue"},{"category":"type","location":"#TurboVec.MaskLengthMismatch","page":"Home","text":"Slot mask length does not equal the number of slots.\n\n\n\n\n\n","title":"TurboVec.MaskLengthMismatch"},{"category":"type","location":"#TurboVec.PreparedLut","page":"Home","text":"Per-query tables and score constants shared by both scan kernels.\n\n\n\n\n\n","title":"TurboVec.PreparedLut"},{"category":"type","location":"#TurboVec.QueryBufferNotMultipleOfDim","page":"Home","text":"Query matrix width does not equal the index dim.\n\n\n\n\n\n","title":"TurboVec.QueryBufferNotMultipleOfDim"},{"category":"method","location":"#TurboVec.TurboQuantIndex-Tuple{Integer, Integer}","page":"Home","text":"TurboQuantIndex(dim, bit_width)\n\nConstruct an empty index with a known dimensionality. bit_width must be 2, 3 or 4; dim must be a positive multiple of 8 (and <= 16384).\n\n\n\n\n\n","title":"TurboVec.TurboQuantIndex"},{"category":"method","location":"#TurboVec.TurboQuantIndex-Tuple{Integer}","page":"Home","text":"TurboQuantIndex(bit_width)\n\nConstruct an empty index without committing to a dimensionality; the dim is inferred and locked on the first add!.\n\n\n\n\n\n","title":"TurboVec.TurboQuantIndex"},{"category":"type","location":"#TurboVec.TurboVecError","page":"Home","text":"Base type for every error raised by TurboVec.\n\n\n\n\n\n","title":"TurboVec.TurboVecError"},{"category":"type","location":"#TurboVec.UnknownId","page":"Home","text":"An allowlist id is not present in the index.\n\n\n\n\n\n","title":"TurboVec.UnknownId"},{"category":"type","location":"#TurboVec.ZeroDim","page":"Home","text":"Dimensionality argument was zero.\n\n\n\n\n\n","title":"TurboVec.ZeroDim"},{"category":"method","location":"#Base.copy-Tuple{IdMapIndex}","page":"Home","text":"Deep copy (inner index, id tables).\n\n\n\n\n\n","title":"Base.copy"},{"category":"method","location":"#Base.copy-Tuple{TurboQuantIndex}","page":"Home","text":"Deep copy (codes, scales and calibration; geometry is immutable and shared).\n\n\n\n\n\n","title":"Base.copy"},{"category":"method","location":"#Base.empty!-Tuple{IdMapIndex}","page":"Home","text":"Drop every stored vector/id and the calibration; keep committed geometry.\n\n\n\n\n\n","title":"Base.empty!"},{"category":"method","location":"#Base.empty!-Tuple{TurboQuantIndex}","page":"Home","text":"Drop every stored vector and the calibration; keep committed geometry.\n\n\n\n\n\n","title":"Base.empty!"},{"category":"method","location":"#Base.in-Tuple{Integer, IdMapIndex}","page":"Home","text":"Idiomatic membership: id in index.\n\n\n\n\n\n","title":"Base.in"},{"category":"function","location":"#Base.iterate","page":"Home","text":"Iterate the external ids in slot order.\n\n\n\n\n\n","title":"Base.iterate"},{"category":"method","location":"#Base.keys-Tuple{IdMapIndex}","page":"Home","text":"The external ids as a vector, in slot order (a copy).\n\n\n\n\n\n","title":"Base.keys"},{"category":"method","location":"#Base.size-Tuple{IdMapIndex}","page":"Home","text":"size(index) == (length(index), dim(index)).\n\n\n\n\n\n","title":"Base.size"},{"category":"method","location":"#Base.size-Tuple{TurboQuantIndex}","page":"Home","text":"size(index) == (length(index), dim(index)).\n\n\n\n\n\n","title":"Base.size"},{"category":"method","location":"#TurboVec._calibration_error-Tuple{AbstractVector{Float32}, AbstractVector{Float32}}","page":"Home","text":"Message for the first invalid TQ+ (shift, scale) entry, or nothing.\n\n\n\n\n\n","title":"TurboVec._calibration_error"},{"category":"method","location":"#TurboVec._grow_codes!-Tuple{TurboQuantIndex, Int64}","page":"Home","text":"Grow the blocked code buffer to cover n vectors, zeroing new bytes.\n\n\n\n\n\n","title":"TurboVec._grow_codes!"},{"category":"method","location":"#TurboVec._parallel_ranges-Tuple{Int64}","page":"Home","text":"Contiguous index ranges, one per worker, for row-parallel kernels.\n\n\n\n\n\n","title":"TurboVec._parallel_ranges"},{"category":"method","location":"#TurboVec._prepare_lut-Tuple{TurboQuantIndex, AbstractVector{Float32}, Vector{Float32}, Vector{Float32}}","page":"Home","text":"Rotate the query, apply inverse calibration, and build the scan tables.\n\n\n\n\n\n","title":"TurboVec._prepare_lut"},{"category":"method","location":"#TurboVec._reencode_stored_rows!-Tuple{TurboQuantIndex, Vector{Float32}, Vector{Float32}}","page":"Home","text":"Re-encode every stored row under new_shift/new_scale.\n\n\n\n\n\n","title":"TurboVec._reencode_stored_rows!"},{"category":"method","location":"#TurboVec._scale_error-Tuple{AbstractVector{Float32}}","page":"Home","text":"Message for the first invalid per-vector scale, or nothing.\n\n\n\n\n\n","title":"TurboVec._scale_error"},{"category":"method","location":"#TurboVec._validate_input-Tuple{AbstractMatrix{Float32}, Int64}","page":"Home","text":"Scan for the first non-finite or over-magnitude coordinate.\n\n\n\n\n\n","title":"TurboVec._validate_input"},{"category":"method","location":"#TurboVec.adaptive_simpson-Union{Tuple{F}, Tuple{F, Float64, Float64, Float64, Int64}} where F","page":"Home","text":"Adaptive Simpson's rule, matching the Rust solver's recursion and stopping rule.\n\n\n\n\n\n","title":"TurboVec.adaptive_simpson"},{"category":"method","location":"#TurboVec.add!-Tuple{TurboQuantIndex, AbstractMatrix{Float32}}","page":"Home","text":"add!(index, vectors)\n\nAdd a batch of n × dim Float32 vectors. An empty batch is a no-op.\n\n\n\n\n\n","title":"TurboVec.add!"},{"category":"method","location":"#TurboVec.add!-Tuple{TurboQuantIndex, AbstractVector{Float32}}","page":"Home","text":"Add a single vector (one row).\n\n\n\n\n\n","title":"TurboVec.add!"},{"category":"method","location":"#TurboVec.add_with_ids!-Tuple{IdMapIndex, AbstractMatrix{Float32}, AbstractVector{<:Integer}}","page":"Home","text":"add_with_ids!(index, vectors, ids)\n\nAdd n vectors with n external ids. Rejects ids already present, and duplicates within the batch, before mutating anything.\n\n\n\n\n\n","title":"TurboVec.add_with_ids!"},{"category":"method","location":"#TurboVec.add_with_ids!-Tuple{IdMapIndex, AbstractVector{Float32}, Integer}","page":"Home","text":"Add one vector with one external id.\n\n\n\n\n\n","title":"TurboVec.add_with_ids!"},{"category":"method","location":"#TurboVec.apply_rotation!-Tuple{TurboVec.Rotation, AbstractVector{Float32}}","page":"Home","text":"Rotate one row in place.\n\n\n\n\n\n","title":"TurboVec.apply_rotation!"},{"category":"method","location":"#TurboVec.apply_scaled_into!-Tuple{TurboVec.Rotation, AbstractVector{Float32}, Float32, AbstractVector{Float32}, AbstractVector{Float32}}","page":"Home","text":"apply_scaled_into!(rot, src, inv, dst, scratch)\n\nRotate src scaled by inv into dst, leaving src untouched. Exact op order of the Rust Rotation::apply_scaled_into.\n\n\n\n\n\n","title":"TurboVec.apply_scaled_into!"},{"category":"method","location":"#TurboVec.beta_inc-Tuple{Float64, Float64, Float64}","page":"Home","text":"Regularized incomplete beta function I_x(a,b).\n\n\n\n\n\n","title":"TurboVec.beta_inc"},{"category":"method","location":"#TurboVec.beta_pdf-Tuple{Float64, Float64, Float64}","page":"Home","text":"Beta pdf on [0,1].\n\n\n\n\n\n","title":"TurboVec.beta_pdf"},{"category":"method","location":"#TurboVec.bit_width-Tuple{TurboQuantIndex}","page":"Home","text":"Bits per coordinate (2, 3 or 4).\n\n\n\n\n\n","title":"TurboVec.bit_width"},{"category":"method","location":"#TurboVec.block_size-Tuple{Int64}","page":"Home","text":"Largest power-of-two divisor of dim (always >= 8).\n\n\n\n\n\n","title":"TurboVec.block_size"},{"category":"method","location":"#TurboVec.blocked_codes-Tuple{TurboQuantIndex}","page":"Home","text":"blocked_codes(index) -> Vector{UInt8}\n\nThe sequential blocked code bytes (32 vectors per block, one code byte per lane per byte group) — the layout the scan reads and the file stores. Empty for a lazy or empty index.\n\n\n\n\n\n","title":"TurboVec.blocked_codes"},{"category":"method","location":"#TurboVec.blocked_len-Tuple{Int64, Int64, Int64}","page":"Home","text":"Total size in bytes of the blocked layout for n vectors.\n\n\n\n\n\n","title":"TurboVec.blocked_len"},{"category":"method","location":"#TurboVec.build_query_lut-Tuple{AbstractVector{Float32}, Vector{Float32}, Int64, Int64}","page":"Home","text":"build_query_lut(q_rot_row, centroids, bits, dim) -> QueryLut\n\nBuild the per-query nibble tables in rotated (and TQ+-inverse-calibrated) query space.\n\n\n\n\n\n","title":"TurboVec.build_query_lut"},{"category":"method","location":"#TurboVec.calibrate!-Tuple{IdMapIndex, AbstractMatrix{Float32}}","page":"Home","text":"Fit a TQ+ calibration and re-encode stored rows.\n\n\n\n\n\n","title":"TurboVec.calibrate!"},{"category":"method","location":"#TurboVec.calibrate!-Tuple{TurboQuantIndex, AbstractMatrix{Float32}}","page":"Home","text":"calibrate!(index, sample)\n\nFit a TQ+ per-coordinate calibration from a rows × dim sample. On a populated index every stored row is re-encoded under the new pair.\n\n\n\n\n\n","title":"TurboVec.calibrate!"},{"category":"method","location":"#TurboVec.calibration-Tuple{TurboQuantIndex}","page":"Home","text":"calibration(index) -> Union{Nothing, NamedTuple}\n\nThe committed TQ+ calibration as (shift = …, scale = …), or nothing when the index is uncalibrated. The returned vectors are live internal state — treat them as read-only.\n\n\n\n\n\n","title":"TurboVec.calibration"},{"category":"method","location":"#TurboVec.calibration_state-Tuple{TurboQuantIndex}","page":"Home","text":"true when a TQ+ per-coordinate calibration is committed.\n\n\n\n\n\n","title":"TurboVec.calibration_state"},{"category":"method","location":"#TurboVec.codebook-Tuple{Int64, Int64}","page":"Home","text":"codebook(bits, dim) -> (; boundaries, centroids)\n\nThe canonical Lloyd-Max codebook for bits ∈ {2,3,4} and a positive multiple-of-8 dim. Memoized per (bits, dim).\n\n\n\n\n\n","title":"TurboVec.codebook"},{"category":"method","location":"#TurboVec.codebook_for_write-Tuple{TurboQuantIndex}","page":"Home","text":"codebook_for_write(index) -> (; boundaries, centroids)\n\nThe codebook arrays a file embeds. Populated indexes return the real Lloyd-Max codebook; lazy or empty ones return correctly-sized zero placeholders, which loaders ignore.\n\n\n\n\n\n","title":"TurboVec.codebook_for_write"},{"category":"method","location":"#TurboVec.compute_tqplus_calibration-Tuple{AbstractMatrix{Float32}, Int64, Int64, Vector{Float32}}","page":"Home","text":"compute_tqplus_calibration(rotated, n, dim, centroids) -> (shift, scale)\n\nFit the per-coordinate (shift, scale) pair from n rotated rows (rotated is dim × n). Maps each coordinate's empirical quantiles at the codebook's anchor levels onto the canonical Beta marginal's edges.\n\n\n\n\n\n","title":"TurboVec.compute_tqplus_calibration"},{"category":"method","location":"#TurboVec.contains_id-Tuple{IdMapIndex, Integer}","page":"Home","text":"True if the index currently contains a vector with this external id.\n\n\n\n\n\n","title":"TurboVec.contains_id"},{"category":"method","location":"#TurboVec.dim-Tuple{TurboQuantIndex}","page":"Home","text":"Committed dimensionality; 0 for a lazy, uncommitted index.\n\n\n\n\n\n","title":"TurboVec.dim"},{"category":"method","location":"#TurboVec.dim_opt-Tuple{TurboQuantIndex}","page":"Home","text":"The committed dimensionality, or nothing for a lazy index.\n\n\n\n\n\n","title":"TurboVec.dim_opt"},{"category":"method","location":"#TurboVec.external_ids-Tuple{IdMapIndex}","page":"Home","text":"The external ids in slot order (slot order itself is an implementation detail).\n\n\n\n\n\n","title":"TurboVec.external_ids"},{"category":"method","location":"#TurboVec.extract_codes_lane!-Tuple{AbstractVector{UInt8}, AbstractVector{UInt8}, Int64, Int64, Int64}","page":"Home","text":"extract_codes_lane!(codes, blocked, lane, dim, bits)\n\nInverse of [write_codes_lane!]: recover the dim code values for a lane from the blocked layout.\n\n\n\n\n\n","title":"TurboVec.extract_codes_lane!"},{"category":"method","location":"#TurboVec.first_invalid_coord-Tuple{AbstractVector{Float32}, Integer}","page":"Home","text":"first_invalid_coord(values, dim; max_magnitude = 1e16)\n    -> Union{Nothing, NamedTuple}\n\nScan a flat n * dim buffer for the first coordinate that is not finite or has magnitude >= max_magnitude, and return (vector_index, coord_index, value) with 1-based indices, or nothing when the input is clean. This is the predicate add! and search enforce.\n\n\n\n\n\n","title":"TurboVec.first_invalid_coord"},{"category":"method","location":"#TurboVec.from_bytes-Tuple{Type{TurboQuantIndex}, AbstractVector{UInt8}}","page":"Home","text":"Deserialize an index produced by to_bytes.\n\n\n\n\n\n","title":"TurboVec.from_bytes"},{"category":"function","location":"#TurboVec.from_parts","page":"Home","text":"from_parts(dim, bit_width, n, packed_codes, scales, tqplus_shift, tqplus_scale)\n    -> TurboQuantIndex\n\nRebuild an index from its raw parts, validating everything before constructing: bit width, dim, part lengths, per-vector scale bounds, and the TQ+ calibration bounds. An identity (0, 1) calibration pair is canonicalized to the empty (uncalibrated) representation.\n\n\n\n\n\n","title":"TurboVec.from_parts"},{"category":"method","location":"#TurboVec.is_addable-Tuple{IdMapIndex, AbstractVector{<:Integer}}","page":"Home","text":"is_addable(index, ids) -> Bool\n\nTrue when ids has no duplicates and none of them is already present — exactly the pair of conditions add_with_ids! validates.\n\n\n\n\n\n","title":"TurboVec.is_addable"},{"category":"method","location":"#TurboVec.is_calibrated-Tuple{TurboQuantIndex}","page":"Home","text":"Whether a TQ+ calibration is committed (the idiomatic predicate form).\n\n\n\n\n\n","title":"TurboVec.is_calibrated"},{"category":"method","location":"#TurboVec.is_lazy-Tuple{TurboQuantIndex}","page":"Home","text":"Whether the index is lazy (no committed dim yet).\n\n\n\n\n\n","title":"TurboVec.is_lazy"},{"category":"method","location":"#TurboVec.is_packed_ready-Tuple{TurboQuantIndex}","page":"Home","text":"is_packed_ready(index) -> Bool\n\nAlways true: this port keeps a single materialized code layout, so there is no lazy packed/blocked duality to report on. Kept for API parity with turbovec.\n\n\n\n\n\n","title":"TurboVec.is_packed_ready"},{"category":"method","location":"#TurboVec.is_slots_ready-Tuple{IdMapIndex}","page":"Home","text":"is_slots_ready(index) -> Bool\n\nAlways true: this port maintains the id tables eagerly, so there is no lazy slot-map build to wait for. Kept for API parity with turbovec.\n\n\n\n\n\n","title":"TurboVec.is_slots_ready"},{"category":"method","location":"#TurboVec.load_idmap-Tuple{AbstractString}","page":"Home","text":"Load an IdMapIndex written by write_idmap.\n\n\n\n\n\n","title":"TurboVec.load_idmap"},{"category":"method","location":"#TurboVec.load_idmap-Tuple{IO}","page":"Home","text":"Read an IdMapIndex from an IO source.\n\n\n\n\n\n","title":"TurboVec.load_idmap"},{"category":"method","location":"#TurboVec.load_index-Tuple{AbstractString}","page":"Home","text":"Load a TurboQuantIndex written by write_index.\n\n\n\n\n\n","title":"TurboVec.load_index"},{"category":"method","location":"#TurboVec.load_index-Tuple{IO}","page":"Home","text":"Read a TurboQuantIndex from an IO source.\n\n\n\n\n\n","title":"TurboVec.load_index"},{"category":"method","location":"#TurboVec.max_tqplus_shift-Tuple{Int64}","page":"Home","text":"Largest TQ+ shift magnitude at dim whose bias dot product cannot overflow.\n\n\n\n\n\n","title":"TurboVec.max_tqplus_shift"},{"category":"method","location":"#TurboVec.merge_topk!-Tuple{TurboVec.TopK, TurboVec.TopK}","page":"Home","text":"Merge src into dst, keeping the global top-k.\n\n\n\n\n\n","title":"TurboVec.merge_topk!"},{"category":"method","location":"#TurboVec.min_tqplus_scale-Tuple{Int64}","page":"Home","text":"Smallest TQ+ scale at dim that cannot drive a divided query to overflow.\n\n\n\n\n\n","title":"TurboVec.min_tqplus_scale"},{"category":"method","location":"#TurboVec.move_lane!-Tuple{AbstractVector{UInt8}, Int64, Int64, Int64}","page":"Home","text":"Copy lane src to lane dst across every byte group.\n\n\n\n\n\n","title":"TurboVec.move_lane!"},{"category":"method","location":"#TurboVec.pack_mask-Tuple{AbstractVector{Bool}}","page":"Home","text":"Pack a one-bool-per-slot mask into the little-endian bitset the scan reads.\n\n\n\n\n\n","title":"TurboVec.pack_mask"},{"category":"method","location":"#TurboVec.packed_codes-Tuple{TurboQuantIndex}","page":"Home","text":"packed_codes(index) -> Vector{UInt8}\n\nThe canonical bit-plane encoding of every row: bits * (dim ÷ 8) bytes per vector, plane p's byte c holding bit p of the eight codes in coordinate chunk c (most significant coordinate in bit 7). This is the layout from_parts accepts.\n\n\n\n\n\n","title":"TurboVec.packed_codes"},{"category":"method","location":"#TurboVec.prepare-Tuple{TurboQuantIndex}","page":"Home","text":"No-op kept for API parity: this port has no search caches to warm.\n\n\n\n\n\n","title":"TurboVec.prepare"},{"category":"method","location":"#TurboVec.quantize_scale_pack!-Union{Tuple{CAL}, Tuple{AbstractVector{UInt8}, Int64, AbstractVector{Float32}, Vector{Float32}, Vector{Float32}, Vector{Float32}, Vector{Float32}, Vector{Float32}, Int64, Int64, Float32, Val{CAL}}} where CAL","page":"Home","text":"quantize_scale_pack!(blocked, lane, rot_orig, shift, scale_tq,\n                     inv_scale_tq, centroids, boundaries, bits, dim,\n                     norm) -> Float32\n\nQuantize one rotated unit row under the calibration (shift, scale_tq), write its code bytes into the blocked layout at lane, and return the stored length-renormalization scale. An uncalibrated index passes the identity pair (shift == 0, scale_tq == 1), which is arithmetically exact.\n\n\n\n\n\n","title":"TurboVec.quantize_scale_pack!"},{"category":"method","location":"#TurboVec.remove!-Tuple{IdMapIndex, Integer}","page":"Home","text":"Remove the vector with external id. Returns true if present.\n\n\n\n\n\n","title":"TurboVec.remove!"},{"category":"method","location":"#TurboVec.rotate_batch!-Tuple{AbstractMatrix{Float32}, Vector{Float32}, AbstractMatrix{Float32}, TurboVec.Rotation}","page":"Home","text":"rotate_batch!(rotated, norms, X, rotation)\n\nRotate the rows of the n × dim matrix X (normalizing each by 1/||row||) into the dim × n output rotated, returning per-row norms. rotated[:, i] is row i's rotated unit vector.\n\nEach worker owns its scratch buffers, so the kernel is race-free.\n\n\n\n\n\n","title":"TurboVec.rotate_batch!"},{"category":"method","location":"#TurboVec.scale_lut-Tuple{TurboVec.QueryLut}","page":"Home","text":"scale_lut(lut) -> Vector{Float32}\n\nscale * Float32(entry) for every table entry. Bit-identical to the per-lookup multiply the Rust kernel performs, hoisted out of the scan.\n\n\n\n\n\n","title":"TurboVec.scale_lut"},{"category":"method","location":"#TurboVec.scales-Tuple{TurboQuantIndex}","page":"Home","text":"Per-vector length-renormalization scales, one per slot.\n\nReturns the index's live internal array — treat it as read-only.\n\n\n\n\n\n","title":"TurboVec.scales"},{"category":"method","location":"#TurboVec.search-Tuple{IdMapIndex, AbstractMatrix{Float32}, Integer}","page":"Home","text":"search(index, queries, k; allowlist = nothing) -> (scores, ids)\n\nTop-k ids for each of the nq × dim query rows. allowlist, when given, restricts results to those external ids; it is deduplicated, and k_eff = min(k, number of unique allowlisted ids). An empty allowlist or an unknown id is an error, not a panic.\n\n\n\n\n\n","title":"TurboVec.search"},{"category":"method","location":"#TurboVec.search-Tuple{IdMapIndex, AbstractVector{Float32}, Integer}","page":"Home","text":"Single-query convenience: returns 1 × k_eff matrices.\n\n\n\n\n\n","title":"TurboVec.search"},{"category":"method","location":"#TurboVec.search-Tuple{TurboQuantIndex, AbstractMatrix{Float32}, Integer}","page":"Home","text":"search(index, queries, k; mask = nothing) -> (scores, indices)\n\nTop-k nearest slots for each of the nq × dim Float32 query rows. Returns nq × k_eff matrices, k_eff = min(k, length(index)), sorted by descending score within each row.\n\nmask, when given, is a Bool vector with one entry per slot: only true slots contribute, and k_eff = min(k, length(index), count(mask)). The index is asked for exactly k_eff results — there is no masked over-fetch.\n\n\n\n\n\n","title":"TurboVec.search"},{"category":"method","location":"#TurboVec.search-Tuple{TurboQuantIndex, AbstractVector{Float32}, Integer}","page":"Home","text":"Single-query convenience: returns 1 × k_eff matrices.\n\n\n\n\n\n","title":"TurboVec.search"},{"category":"method","location":"#TurboVec.serialized_len-Tuple{IdMapIndex}","page":"Home","text":"Exact on-disk length of an id-map index (positional image + id table).\n\n\n\n\n\n","title":"TurboVec.serialized_len"},{"category":"method","location":"#TurboVec.serialized_len-Tuple{TurboQuantIndex}","page":"Home","text":"Exact on-disk length of a positional index (header + body).\n\n\n\n\n\n","title":"TurboVec.serialized_len"},{"category":"method","location":"#TurboVec.simd_norm-Tuple{AbstractVector{Float32}, Int64}","page":"Home","text":"Fixed-order 8-chain Euclidean norm of one row (matches Rust simd_norm).\n\n\n\n\n\n","title":"TurboVec.simd_norm"},{"category":"method","location":"#TurboVec.sorted_results-Tuple{TurboVec.TopK}","page":"Home","text":"Results sorted by descending score (ties by ascending index).\n\n\n\n\n\n","title":"TurboVec.sorted_results"},{"category":"method","location":"#TurboVec.swap_remove!-Tuple{TurboQuantIndex, Integer}","page":"Home","text":"swap_remove!(index, slot) -> Int\n\nRemove the vector at 1-based slot in O(1) by moving the last vector into it. Returns the old index of the moved vector. Order is not preserved.\n\n\n\n\n\n","title":"TurboVec.swap_remove!"},{"category":"method","location":"#TurboVec.to_bytes-Tuple{TurboQuantIndex}","page":"Home","text":"to_bytes(index) -> Vector{UInt8}\n\nSerialize an index to an in-memory buffer using the same versioned layout as write_index.\n\n\n\n\n\n","title":"TurboVec.to_bytes"},{"category":"method","location":"#TurboVec.tqplus_scale-Tuple{TurboQuantIndex}","page":"Home","text":"Committed TQ+ scale; empty when uncalibrated.\n\nReturns the index's live internal array — treat it as read-only.\n\n\n\n\n\n","title":"TurboVec.tqplus_scale"},{"category":"method","location":"#TurboVec.tqplus_shift-Tuple{TurboQuantIndex}","page":"Home","text":"Committed TQ+ shift; empty when uncalibrated.\n\nReturns the index's live internal array — treat it as read-only.\n\n\n\n\n\n","title":"TurboVec.tqplus_shift"},{"category":"method","location":"#TurboVec.write_codes_lane!-Tuple{AbstractVector{UInt8}, Int64, AbstractVector{UInt8}, Int64, Int64}","page":"Home","text":"write_codes_lane!(blocked, lane, codes, dim, bits)\n\nWrite one vector's dim code values (0 <= code < 2^bits) into the blocked layout at lane (0-based).\n\n\n\n\n\n","title":"TurboVec.write_codes_lane!"},{"category":"method","location":"#TurboVec.write_idmap-Tuple{AbstractString, IdMapIndex}","page":"Home","text":"write_idmap(path, index)\n\nPersist an IdMapIndex, external ids included.\n\n\n\n\n\n","title":"TurboVec.write_idmap"},{"category":"method","location":"#TurboVec.write_idmap-Tuple{IO, IdMapIndex}","page":"Home","text":"Serialize an IdMapIndex to an IO sink in the file layout.\n\n\n\n\n\n","title":"TurboVec.write_idmap"},{"category":"method","location":"#TurboVec.write_index-Tuple{AbstractString, TurboQuantIndex}","page":"Home","text":"write_index(path, index)\n\nPersist a TurboQuantIndex to a single versioned file (fsynced, atomically renamed into place).\n\n\n\n\n\n","title":"TurboVec.write_index"},{"category":"method","location":"#TurboVec.write_index-Tuple{IO, TurboQuantIndex}","page":"Home","text":"Serialize a TurboQuantIndex to an IO sink in the file layout.\n\n\n\n\n\n","title":"TurboVec.write_index"}]
}
